__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float size_x = chf("Width", 1.0f);
        float size_z = chf("Length", 1.0f);
        int cols = chi("Columns", 16);
        int rows = chi("Rows", 16);
        int colored = chb("Color", true) > 0.5f ? 1 : 0;
        if (cols < 1) cols = 1;
        if (cols > 128) cols = 128;
        if (rows < 1) rows = 1;
        if (rows > 128) rows = 128;
        float center_x = chf("Center X", 0.0f);
        float center_y = chf("Center Y", 0.0f);
        float center_z = chf("Center Z", 0.0f);
        float half_x = size_x * 0.5f;
        float half_z = size_z * 0.5f;
        float step_x = size_x / (float)cols;
        float step_z = size_z / (float)rows;
        float inv_x = size_x > 0.0f ? 1.0f / size_x : 0.0f;
        float inv_z = size_z > 0.0f ? 1.0f / size_z : 0.0f;
        int count = 0;
        for (int i = 0; i < cols; i++) {
            float x0 = -half_x + (float)i * step_x;
            float x1 = x0 + step_x;
            for (int j = 0; j < rows; j++) {
                float z0 = -half_z + (float)j * step_z;
                float z1 = z0 + step_z;
                float px[6] = {x0, x1, x1, x0, x0, x1};
                float pz[6] = {z0, z1, z0, z0, z1, z1};
                for (int v = 0; v < 6; v++) {
                    int idx = count++;
                    if (idx < max_vertices) {
                        out_pos[idx * 3 + 0] = center_x + px[v];
                        out_pos[idx * 3 + 1] = center_y;
                        out_pos[idx * 3 + 2] = center_z + pz[v];
                        float fx = (px[v] + half_x) * inv_x;
                        float fz = (pz[v] + half_z) * inv_z;
                        if (colored) {
                            out_col[idx * 3 + 0] = 0.35f + fx * 0.35f;
                            out_col[idx * 3 + 1] = 0.45f + fz * 0.35f;
                            out_col[idx * 3 + 2] = 0.85f;
                        } else {
                            out_col[idx * 3 + 0] = 0.8f;
                            out_col[idx * 3 + 1] = 0.8f;
                            out_col[idx * 3 + 2] = 0.8f;
                        }
                    }
                }
            }
        }
        *out_count = count;
    }
}
